import { createApp } from "/work/src/app.ts";

const clock = () => new Date("2026-10-01T08:00:00Z");
const app = createApp({ clock });

const mkCoupon = (over: any = {}) =>
  app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...over,
  });

const log = (label: string, r: any) => console.log(label, r.status, JSON.stringify(r.body));

// percent
mkCoupon();
app.request("POST", "/orders", { customer: "alice", amountCents: 12000 });
log("apply percent", app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" }));
log("apply twice", app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" }));
log("coupon used", app.request("GET", "/coupons/SAVE20"));

// fixed with cap + min
mkCoupon({ code: "FLAT", type: "FIXED", value: 5000, maxDiscountCents: 2000, minAmountCents: 3000 });
app.request("POST", "/orders", { customer: "bob", amountCents: 4000 });
log("fixed cap", app.request("POST", "/orders/2/apply-coupon", { couponCode: "FLAT" }));

// min not met
app.request("POST", "/orders", { customer: "carl", amountCents: 1000 });
log("min not met", app.request("POST", "/orders/3/apply-coupon", { couponCode: "FLAT" }));

// disabled
mkCoupon({ code: "OFF", status: "DISABLED" });
app.request("POST", "/orders", { customer: "d", amountCents: 5000 });
log("disabled", app.request("POST", "/orders/4/apply-coupon", { couponCode: "OFF" }));

// expired
mkCoupon({ code: "OLD", validFrom: "2025-01-01T00:00:00Z", validUntil: "2025-12-31T00:00:00Z" });
app.request("POST", "/orders", { customer: "e", amountCents: 5000 });
log("expired", app.request("POST", "/orders/5/apply-coupon", { couponCode: "OLD" }));

// not yet valid
mkCoupon({ code: "NEW", validFrom: "2027-01-01T00:00:00Z", validUntil: "2027-12-31T00:00:00Z" });
app.request("POST", "/orders", { customer: "f", amountCents: 5000 });
log("not yet", app.request("POST", "/orders/6/apply-coupon", { couponCode: "NEW" }));

// usage limit
mkCoupon({ code: "ONE", type: "FIXED", value: 100, usageLimit: 1 });
app.request("POST", "/orders", { customer: "g", amountCents: 5000 });
app.request("POST", "/orders", { customer: "h", amountCents: 5000 });
log("limit first", app.request("POST", "/orders/7/apply-coupon", { couponCode: "ONE" }));
log("limit second", app.request("POST", "/orders/8/apply-coupon", { couponCode: "ONE" }));

// greater than amount
mkCoupon({ code: "BIG", type: "FIXED", value: 999999 });
app.request("POST", "/orders", { customer: "i", amountCents: 5000 });
log("big", app.request("POST", "/orders/9/apply-coupon", { couponCode: "BIG" }));

